export interface ResolverResult<T = unknown> {
  success: boolean;
  shape: string;
  body: T;
  details?: Record<string, unknown>;
}

export interface Impulse {
  id: string;
  type: string;
  pointer: Record<string, unknown>;
  content: string;
  loaded: boolean;
  budget: number;
  priority: 'low' | 'medium' | 'high';
  metadata: Record<string, unknown>;
  createdAt: number;
}
